#if DEBUG
import AVFoundation
import Foundation
import Speech

/// Simulator voice probe [internal: A2i, E-162]: feeds an audio file generated by `say` in place of the microphone, driving the production dictation pipeline.
/// Triggered only by launch arg `-VOICE_SIM_PROBE record|auth|rolling|analyzer <audio path relative to the data container>` or `-VOICE_SIM_PROBE recover`;
/// results are written to the data container at tmp/voice-sim-probe/<mode>.json, read by scripts/voice-sim-probe.sh via simctl get_app_container.
@MainActor
enum VoiceSimProbe {

    static let slotKey = "probe:voice-sim"
    static let outputDirectory = "tmp/voice-sim-probe"

    static func run(mode: String, arguments: [String]) async {
        switch mode {
        case "record":
            guard let index = arguments.firstIndex(of: "record"), index + 1 < arguments.count else {
                write("record", ["phase": "error", "error": "missing audio path"])
                return
            }
            await record(audioPath: arguments[index + 1])
        case "recover":
            await recover()
        case "s0":
            await VoiceS0Probe.run(arguments: arguments)
        case "s5-dictation":
            await VoiceS5SimDictation.run(arguments: arguments)
        case "s5-conversation":
            await VoiceS5SimConversation.run(arguments: arguments)
        case RealtimeEchoBench.mode: await RealtimeEchoBench.run(arguments: arguments)
        case "auth", "rolling", "analyzer":
            guard let index = arguments.firstIndex(of: mode), index + 1 < arguments.count else {
                write(mode, ["phase": "error", "error": "missing audio path"])
                return
            }
            switch mode {
            case "auth": await auth(audioPath: arguments[index + 1])
            case "rolling": await rolling(audioPath: arguments[index + 1])
            default: await analyzer(audioPath: arguments[index + 1])
            }
        default:
            write(mode, ["phase": "error", "error": "unknown mode \(mode)"])
        }
    }

    // MARK: record

    /// Clears the slot left by the previous run, starts recording, then writes the fed seconds every 0.5 s until terminated by simctl.
    private static func record(audioPath: String) async {
        let url = URL(fileURLWithPath: NSHomeDirectory()).appendingPathComponent(audioPath)
        let capture: FileAudioCapture
        do {
            capture = try FileAudioCapture(url: url)
            try clearSlot()
        } catch {
            write("record", ["phase": "error", "error": "\(error)"])
            return
        }
        let hub = DictationHub(factory: { try DictationHub.makeProduction(providers: $0, capture: capture) })
        guard let controller = hub.controller else {
            write("record", ["phase": "error", "error": "controller unavailable"])
            return
        }
        controller.bind(slotKey: slotKey)
        await controller.bindLoad?.value
        await controller.micTapped()
        guard case .recording = controller.state else {
            write("record", ["phase": "error", "error": "not recording", "state": describe(controller.state)])
            return
        }
        while true {
            write("record", [
                "phase": "recording",
                "state": describe(controller.state),
                "fedSec": capture.fedSeconds,
                "fileSec": capture.fileSeconds,
            ])
            try? await Task.sleep(nanoseconds: 500_000_000)
            // Keep-alive: the hub and controller must live until the process is killed.
            withExtendedLifetime(hub) {}
        }
    }

    // MARK: recover

    /// Cold launch binds the same slot: production should restore it as interrupted; then "transcribe" runs the system engine over the recording in the slot.
    private static func recover() async {
        let hub = DictationHub(factory: { try DictationHub.makeProduction(providers: $0) })
        guard let controller = hub.controller else {
            write("recover", ["phase": "error", "error": "controller unavailable"])
            return
        }
        controller.bind(slotKey: slotKey)
        await controller.bindLoad?.value
        let recoveredState = describe(controller.state)
        await controller.pendingDurationLoad?.value
        let durationSec = controller.pendingDurationSec
        var report: [String: Any] = ["phase": "transcribing", "recoveredState": recoveredState]
        if let durationSec { report["durationSec"] = durationSec }
        write("recover", report)

        var transcript: String?
        var events: [String] = []
        controller.onEvent = { event in
            events.append("\(event)")
            if case .insert(let text) = event { transcript = text }
        }
        await controller.finish(.insert)
        report["phase"] = "done"
        report["finalState"] = describe(controller.state)
        report["events"] = events
        if let transcript { report["transcript"] = transcript }
        write("recover", report)
        withExtendedLifetime(hub) {}
    }

    // MARK: auth

    /// Triggers the authorization request through the production start-recording flow [internal: E-163; evidence is the tccd log, no screenshot]. The system dialog is not tapped:
    /// while it is shown, micTapped stays pending; the script terminates the app after reading the log. If authorization is already in place, record 3 s, transcribe, and write done.
    private static func auth(audioPath: String) async {
        let url = URL(fileURLWithPath: NSHomeDirectory()).appendingPathComponent(audioPath)
        let capture: FileAudioCapture
        do {
            capture = try FileAudioCapture(url: url)
            try clearSlot()
        } catch {
            write("auth", ["phase": "error", "error": "\(error)"])
            return
        }
        let hub = DictationHub(factory: { try DictationHub.makeProduction(providers: $0, capture: capture) })
        guard let controller = hub.controller else {
            write("auth", ["phase": "error", "error": "controller unavailable"])
            return
        }
        var report: [String: Any] = ["phase": "requesting", "osVersion": osVersion]
        write("auth", report)
        controller.bind(slotKey: slotKey)
        await controller.bindLoad?.value
        await controller.micTapped()
        report["startState"] = describe(controller.state)
        if case .recording = controller.state {
            // Local time in the tccd log format, so the script can split requests before / after recording starts.
            let formatter = DateFormatter()
            formatter.locale = Locale(identifier: "en_US_POSIX")
            formatter.dateFormat = "yyyy-MM-dd HH:mm:ss.SSS"
            report["recordingAt"] = formatter.string(from: Date())
            report["phase"] = "recording"
            write("auth", report)
            try? await Task.sleep(nanoseconds: 3_000_000_000)
            var transcript: String?
            controller.onEvent = { event in
                if case .insert(let text) = event { transcript = text }
            }
            await controller.finish(.insert)
            if let transcript { report["transcript"] = transcript }
        }
        report["phase"] = "done"
        report["finalState"] = describe(controller.state)
        write("auth", report)
        withExtendedLifetime(hub) {}
    }

    // MARK: rolling

    /// Recordings longer than 1 minute are transcribed in full by the production system engine (en-US).
    /// segments come from replaying the same file through the production RollingMeter with the transcribe chunking; reported only on iOS 18-25
    /// (SFSpeechRecognizer only, which needs rolling). iOS 26+ SpeechAnalyzer does not roll.
    private static func rolling(audioPath: String) async {
        let url = URL(fileURLWithPath: NSHomeDirectory()).appendingPathComponent(audioPath)
        var report: [String: Any] = ["phase": "transcribing", "osVersion": osVersion]
        let durationSec: Double
        do {
            let file = try AVAudioFile(forReading: url, commonFormat: .pcmFormatFloat32, interleaved: false)
            durationSec = Double(file.length) / file.processingFormat.sampleRate
            if #unavailable(iOS 26) {
                report["segments"] = try meterSegments(file)
            }
        } catch {
            write("rolling", ["phase": "error", "error": "\(error)"])
            return
        }
        report["durationSec"] = durationSec
        write("rolling", report)
        let engine = SystemSTTEngine.makeDefault(assets: SpeechAssetManager.makeDefault())
        let recording = RecordingResult(url: url, durationSec: durationSec, envelope: [])
        do {
            report["transcript"] = try await engine.transcribe(recording, language: "en-US")
            report["phase"] = "done"
        } catch {
            report["phase"] = "error"
            report["error"] = "\(error)"
        }
        write("rolling", report)
    }

    /// Segment count = 1 + the number of cut points RollingMeter yields under the same transcribe chunking (fileChunkFrames).
    private static func meterSegments(_ file: AVAudioFile) throws -> Int {
        let format = file.processingFormat
        var meter = RollingMeter(sampleRate: format.sampleRate, enabled: true)
        var segments = 1
        file.framePosition = 0
        while file.framePosition < file.length {
            guard let buffer = AVAudioPCMBuffer(pcmFormat: format, frameCapacity: SystemSTTEngine.fileChunkFrames) else {
                break
            }
            try file.read(into: buffer)
            if buffer.frameLength == 0 { break }
            segments += meter.consume(buffer).count
        }
        return segments
    }

    // MARK: analyzer

#if targetEnvironment(simulator)

    /// iOS 26+: records the install-state sequence and progress of the SpeechTranscriber language asset, plus maximumReservedLocales;
    /// transcribes via the system engine assembled as in makeDefault (backends are wrapped to record attempt results only, selection logic unchanged);
    /// once the asset is installed, verifies that over-limit reservation releases the least recently used locale.
    private static func analyzer(audioPath: String) async {
        let report: [String: Any] = ["phase": "preparing", "osVersion": osVersion]
        guard #available(iOS 26, *) else {
            var unsupported = report
            unsupported["phase"] = "done"
            unsupported["skipped"] = "requires iOS 26"
            write("analyzer", unsupported)
            return
        }
        await analyzerRun(audioPath: audioPath, report: report)
    }

    @available(iOS 26, *)
    private static func analyzerRun(audioPath: String, report initial: [String: Any]) async {
        var report = initial
        let url = URL(fileURLWithPath: NSHomeDirectory()).appendingPathComponent(audioPath)
        let durationSec: Double
        do {
            let file = try AVAudioFile(forReading: url)
            durationSec = Double(file.length) / file.processingFormat.sampleRate
        } catch {
            write("analyzer", ["phase": "error", "error": "\(error)"])
            return
        }
        report["durationSec"] = durationSec
        let inventory = SystemSpeechAssetInventory()
        let requested = Locale(identifier: "en-US")
        let locale = await SpeechTranscriber.supportedLocale(equivalentTo: requested) ?? requested
        let limit = await inventory.maximumReservedLocales()
        report["maximumReservedLocales"] = limit
        report["speechTranscriberAvailable"] = SpeechTranscriber.isAvailable
        report["locale"] = SpeechAssetManager.localeKey(locale)
        let reservedBefore = await inventory.reservedLocales()
        report["reservedBefore"] = reservedBefore.map(SpeechAssetManager.localeKey)
        let statusBefore = await AssetInventory.status(
            forModules: [SystemSpeechAssetInventory.module(.speechTranscriber, locale: locale)]
        )
        report["assetStatusBefore"] = "\(statusBefore)"
        write("analyzer", report)

        // Asset install: production SpeechAssetManager + system inventory, samples state every 0.1 s, records changes only.
        let suite = "probe.voice-sim.analyzer"
        guard let defaults = UserDefaults(suiteName: suite) else {
            write("analyzer", ["phase": "error", "error": "UserDefaults suite \(suite) unavailable"])
            return
        }
        defaults.removePersistentDomain(forName: suite)
        let manager = SpeechAssetManager(inventory: inventory, defaults: defaults)
        let sampler = StateSampler()
        let sampling = Task { @MainActor in
            while !Task.isCancelled {
                sampler.record(manager.state(.speechTranscriber, locale: locale))
                try? await Task.sleep(nanoseconds: 100_000_000)
            }
        }
        do {
            try await manager.prepare(.speechTranscriber, locale: locale)
        } catch {
            report["assetError"] = "\(error)"
        }
        sampling.cancel()
        let finalState = manager.state(.speechTranscriber, locale: locale)
        sampler.record(finalState)
        report["assetStates"] = sampler.states
        report["assetProgress"] = sampler.progress
        report["assetFinalState"] = StateSampler.name(finalState)
        report["phase"] = "transcribing"
        write("analyzer", report)

        // Transcription: components match SystemSTTEngine.makeDefault (iOS 26 branch), each backend wrapped to record.
        let attempts = BackendAttemptLog()
        let engine = SystemSTTEngine(
            speechTranscriber: RecordingBackend(SpeechAnalyzerBackend(kind: .speechTranscriber, assets: manager), log: attempts),
            dictationTranscriber: RecordingBackend(SpeechAnalyzerBackend(kind: .dictationTranscriber, assets: manager), log: attempts),
            speechRecognizer: RecordingBackend(SFSpeechRecognizerBackend(), log: attempts),
            analyzerAvailable: true,
            authorizer: SystemSpeechAuthorizer()
        )
        do {
            report["transcript"] = try await engine.transcribe(
                RecordingResult(url: url, durationSec: durationSec, envelope: []),
                language: "en-US"
            )
        } catch {
            report["transcribeError"] = "\(error)"
        }
        report["backendAttempts"] = attempts.entries
        if let backend = attempts.opened { report["backend"] = backend }
        report["dictationDiagnosis"] = await dictationDiagnosis(audioURL: url, requested: requested)

        // Eviction: checked only once the asset is installed; ReservationOnlyInventory skips downloads only, reservation and release go through the system.
        if case .installed = finalState {
            report["phase"] = "evicting"
            write("analyzer", report)
            guard let eviction = await evictionCheck(inventory: inventory, limit: limit, keep: locale) else {
                write("analyzer", ["phase": "error", "error": "UserDefaults suite probe.voice-sim.eviction unavailable"])
                return
            }
            report["eviction"] = eviction
        } else {
            report["eviction"] = ["skipped": "language asset not installed (\(StateSampler.name(finalState)))"]
        }
        report["phase"] = "done"
        write("analyzer", report)
    }

    /// Actual values of each DictationTranscriber step when a session starts (asset status, bestAvailableAudioFormat, format converter), to locate where it falls back to another backend.
    @available(iOS 26, *)
    private static func dictationDiagnosis(audioURL: URL, requested: Locale) async -> [String: Any] {
        var result: [String: Any] = [:]
        guard let locale = await DictationTranscriber.supportedLocale(equivalentTo: requested) else {
            result["supportedLocale"] = "none"
            return result
        }
        result["supportedLocale"] = SpeechAssetManager.localeKey(locale)
        let module = DictationTranscriber(locale: locale, preset: .longDictation)
        result["assetStatus"] = "\(await AssetInventory.status(forModules: [module]))"
        guard let file = try? AVAudioFile(forReading: audioURL) else { return result }
        let source = file.processingFormat
        result["sourceFormat"] = "\(source)"
        let best = await SpeechAnalyzer.bestAvailableAudioFormat(compatibleWith: [module], considering: source)
        let bestWithout = await SpeechAnalyzer.bestAvailableAudioFormat(compatibleWith: [module])
        result["bestFormat"] = best.map { "\($0)" } ?? "nil"
        result["bestFormatWithoutSource"] = bestWithout.map { "\($0)" } ?? "nil"
        if let best { result["converter"] = PCMFormatConverter(from: source, to: best) != nil }
        return result
    }

    /// After clearing reservations, prepares limit+1 locales in turn (clock advances +1 s each), asserting the first (least recently used) is released and the rest stay reserved.
    @available(iOS 26, *)
    private static func evictionCheck(
        inventory: SystemSpeechAssetInventory,
        limit: Int,
        keep: Locale
    ) async -> [String: Any]? {
        guard limit > 0 else { return ["skipped": "maximumReservedLocales is \(limit)"] }
        let keepKey = SpeechAssetManager.localeKey(keep)
        var seenLanguages: Set<String> = []
        var picks: [Locale] = []
        for candidate in await SpeechTranscriber.supportedLocales {
            let key = SpeechAssetManager.localeKey(candidate)
            let language = candidate.language.languageCode?.identifier ?? key
            guard key != keepKey, seenLanguages.insert(language).inserted else { continue }
            picks.append(candidate)
            if picks.count == limit + 1 { break }
        }
        guard picks.count == limit + 1 else {
            return ["skipped": "only \(picks.count) supported locales for limit \(limit)"]
        }
        for reserved in await inventory.reservedLocales() { await inventory.release(reserved) }
        let suite = "probe.voice-sim.eviction"
        // No separate suite: return nil so the caller reports the error; do not fall back to .standard (it would clear the app's own settings).
        guard let defaults = UserDefaults(suiteName: suite) else { return nil }
        defaults.removePersistentDomain(forName: suite)
        let clock = ProbeClock()
        let manager = SpeechAssetManager(
            inventory: ReservationOnlyInventory(base: inventory),
            defaults: defaults,
            now: { clock.tick() }
        )
        var errors: [String] = []
        for pick in picks {
            do {
                try await manager.prepare(.speechTranscriber, locale: pick)
            } catch {
                errors.append("\(SpeechAssetManager.localeKey(pick)): \(error)")
            }
        }
        let reservedAfter = Set(await inventory.reservedLocales().map(SpeechAssetManager.localeKey))
        let keys = picks.map(SpeechAssetManager.localeKey)
        // Cleanup: release the test locales and re-reserve en-US.
        for reserved in await inventory.reservedLocales() { await inventory.release(reserved) }
        try? await inventory.reserve(keep)
        return [
            "locales": keys,
            "reservedAfter": reservedAfter.sorted(),
            "oldestReleased": !reservedAfter.contains(keys[0]),
            "othersKept": keys.dropFirst().allSatisfy(reservedAfter.contains),
            "errors": errors,
        ]
    }
#else
    /// The device does not run the analyzer probe: it clears reserved locales and changes system language assets.
    private static func analyzer(audioPath: String) async {
        write("analyzer", ["phase": "error", "error": "analyzer probe runs only on the simulator"])
    }
#endif

    // MARK: output

    private static var osVersion: String {
        let version = ProcessInfo.processInfo.operatingSystemVersion
        return "\(version.majorVersion).\(version.minorVersion)"
    }

    /// Clears the slot left by the previous run.
    private static func clearSlot() throws {
        let store = try RecordingStore(root: try RecordingStore.productionRoot())
        try? FileManager.default.removeItem(at: store.audioURL(for: slotKey))
        try? FileManager.default.removeItem(at: store.sidecarURL(for: slotKey))
    }

    private static func describe(_ state: DictationState) -> String {
        switch state {
        case .recording: return "recording"
        case .transcribing: return "transcribing"
        default: return "\(state)"
        }
    }

    private static func write(_ name: String, _ object: [String: Any]) {
        let directory = URL(fileURLWithPath: NSHomeDirectory()).appendingPathComponent(outputDirectory)
        try? FileManager.default.createDirectory(at: directory, withIntermediateDirectories: true)
        guard let data = try? JSONSerialization.data(withJSONObject: object, options: [.sortedKeys]) else { return }
        try? data.write(to: directory.appendingPathComponent("\(name).json"), options: .atomic)
    }
}

/// Feeds the audio file as a live microphone: non-interleaved Float32, one 0.1 s block at a time; after the file ends it feeds tailSilenceSeconds of silence,
/// then stops feeding (capture itself is not stopped).
nonisolated final class FileAudioCapture: AudioCapture, @unchecked Sendable {

    let inputFormat: AVAudioFormat
    let fileSeconds: Double
    private let file: AVAudioFile
    private let queue = DispatchQueue(label: "VoiceSimProbe.FileAudioCapture")
    private let lock = NSLock()
    private var generation = 0
    private var fedFrames: AVAudioFramePosition = 0
    private var startedUptime: UInt64?
    private let tailFrames: AVAudioFramePosition

    init(url: URL, tailSilenceSeconds: Double = 0) throws {
        file = try AVAudioFile(forReading: url, commonFormat: .pcmFormatFloat32, interleaved: false)
        inputFormat = file.processingFormat
        fileSeconds = Double(file.length) / file.processingFormat.sampleRate
        tailFrames = AVAudioFramePosition(max(0, tailSilenceSeconds) * file.processingFormat.sampleRate)
    }

    /// Total seconds of file plus tail silence: fedSeconds reaching this value means feeding is complete.
    var totalSeconds: Double { fileSeconds + Double(tailFrames) / inputFormat.sampleRate }

    /// Time of the most recent start (DispatchTime uptime in ns); nil if never started.
    var startedAtUptime: UInt64? {
        lock.lock()
        defer { lock.unlock() }
        return startedUptime
    }

    /// Seconds already handed to the handlers.
    var fedSeconds: Double {
        lock.lock()
        defer { lock.unlock() }
        return Double(fedFrames) / inputFormat.sampleRate
    }

    @discardableResult
    func start(handlers: [AudioBufferHandler]) throws -> AVAudioFormat {
        lock.lock()
        generation += 1
        let current = generation
        fedFrames = 0
        startedUptime = DispatchTime.now().uptimeNanoseconds
        lock.unlock()
        queue.async { [self] in pump(handlers: handlers, generation: current) }
        return inputFormat
    }

    func stop() {
        lock.lock()
        generation += 1
        lock.unlock()
    }

    private func isAlive(_ current: Int) -> Bool {
        lock.lock()
        defer { lock.unlock() }
        return generation == current
    }

    private func pump(handlers: [AudioBufferHandler], generation current: Int) {
        let rate = inputFormat.sampleRate
        let chunk = AVAudioFrameCount(rate / 10)
        let started = DispatchTime.now().uptimeNanoseconds
        var position: AVAudioFramePosition = 0
        var silenceLeft = tailFrames
        // Reset runs on the serial queue: the previous pump has exited, so it cannot race on the same file cursor.
        file.framePosition = 0
        while true {
            guard isAlive(current),
                  let buffer = AVAudioPCMBuffer(pcmFormat: inputFormat, frameCapacity: chunk)
            else { return }
            if file.framePosition < file.length {
                guard (try? file.read(into: buffer, frameCount: chunk)) != nil, buffer.frameLength > 0 else { return }
            } else {
                // File fully read: pad with silence (new buffer is zero-filled).
                guard silenceLeft > 0 else { return }
                let frames = AVAudioFrameCount(min(AVAudioFramePosition(chunk), silenceLeft))
                buffer.frameLength = frames
                for channel in 0..<Int(inputFormat.channelCount) {
                    if let data = buffer.floatChannelData?[channel] { data.update(repeating: 0, count: Int(frames)) }
                }
                silenceLeft -= AVAudioFramePosition(frames)
            }
            // stop may have happened while reading the file: check again so no extra block is pushed after stop.
            guard isAlive(current) else { return }
            let time = AVAudioTime(sampleTime: position, atRate: rate)
            for handler in handlers { handler(buffer, time) }
            position += AVAudioFramePosition(buffer.frameLength)
            lock.lock()
            if generation == current { fedFrames = position }
            lock.unlock()
            // Real-time pacing: the next block is fed at the time matching the fed duration.
            let due = started + UInt64(Double(position) / rate * 1_000_000_000)
            let now = DispatchTime.now().uptimeNanoseconds
            if due > now { usleep(useconds_t((due - now) / 1000)) }
        }
    }
}
/// Asset install-state sampling: records changes only; installing progress is recorded separately.
@MainActor
final class StateSampler {
    private(set) var states: [String] = []
    private(set) var progress: [Double] = []

    func record(_ state: SpeechAssetInstallState) {
        let name = Self.name(state)
        if states.last != name { states.append(name) }
        if case .installing(let fraction) = state, progress.last != fraction { progress.append(fraction) }
    }

    static func name(_ state: SpeechAssetInstallState) -> String {
        switch state {
        case .notInstalled: return "notInstalled"
        case .installing: return "installing"
        case .installed: return "installed"
        case .failed: return "failed"
        }
    }
}

/// Fake clock advancing +1 s per call, so the recency order of use is deterministic.
@MainActor
final class ProbeClock {
    private var seconds: Double = 1_000_000
    func tick() -> Date {
        seconds += 1
        return Date(timeIntervalSince1970: seconds)
    }
}

/// Backend attempt log: result of each supports / startSegment; the last backend to open a segment successfully is the actual backend.
nonisolated final class BackendAttemptLog: @unchecked Sendable {
    private let lock = NSLock()
    private var items: [String] = []
    private var openedKind: String?

    func add(_ entry: String, opened kind: SystemSTTBackendKind? = nil) {
        lock.lock()
        defer { lock.unlock() }
        items.append(entry)
        if let kind { openedKind = kind.rawValue }
    }

    var entries: [String] {
        lock.lock()
        defer { lock.unlock() }
        return items
    }

    var opened: String? {
        lock.lock()
        defer { lock.unlock() }
        return openedKind
    }
}

/// Pass-through backend wrapper that only records.
nonisolated struct RecordingBackend: SystemSTTBackend {
    let base: any SystemSTTBackend
    let log: BackendAttemptLog

    init(_ base: any SystemSTTBackend, log: BackendAttemptLog) {
        self.base = base
        self.log = log
    }

    var kind: SystemSTTBackendKind { base.kind }
    var requiresRolling: Bool { base.requiresRolling }

    func supports(_ locale: Locale) async -> Bool {
        let supported = await base.supports(locale)
        if !supported { log.add("\(kind.rawValue): unsupported \(locale.identifier)") }
        return supported
    }

    func startSegment(
        locale: Locale,
        format: AVAudioFormat,
        onResult: @escaping @Sendable (SystemSTTResult) -> Void
    ) async throws -> any SystemSTTSegment {
        do {
            let segment = try await base.startSegment(locale: locale, format: format, onResult: onResult)
            log.add("\(kind.rawValue): opened", opened: kind)
            return segment
        } catch {
            log.add("\(kind.rawValue): \(error)")
            throw error
        }
    }
}

/// Reservation and release go through the system and install is treated as complete: only verifies SpeechAssetManager's over-limit release, without downloading multiple locales.
@available(iOS 26, *)
nonisolated struct ReservationOnlyInventory: SpeechAssetInventory {
    let base: SystemSpeechAssetInventory

    func maximumReservedLocales() async -> Int { await base.maximumReservedLocales() }
    func reservedLocales() async -> [Locale] { await base.reservedLocales() }
    func reserve(_ locale: Locale) async throws { try await base.reserve(locale) }
    func release(_ locale: Locale) async { await base.release(locale) }
    func isInstalled(_ module: SpeechAssetModule, locale: Locale) async -> Bool { true }
    func install(
        _ module: SpeechAssetModule,
        locale: Locale,
        progress: @escaping @MainActor @Sendable (Double) -> Void
    ) async throws {}
}
#endif
